Follow this complete example.
```swift
class Notice {
    func message() -> String {
        return "Ready"
    }
}
class UrgentNotice: Notice {
    override func message() -> String {
        return super.message() + " now"
    }
}
let basic = Notice()
let selected: Notice = UrgentNotice()
print(basic.message())
print(selected.message())
```
Output:
```text
Ready
Ready now
```

